    # ------------------------------------------------------------------
    # Bucket classifiers
    # ------------------------------------------------------------------

    @staticmethod
    def heat_bucket(percent: int) -> str:
        """Classify a utilization percentage into a heatmap bucket."""
        if percent < HEAT_LOW:
            return "low"
        if percent < HEAT_MID:
            return "mid"
        if percent <= HEAT_HIGH:
            return "high"
        return "over"

    @staticmethod
    def gesamt_bucket(free_days: float) -> str:
        """Classify free days into a gesamt bucket."""
        # Free days come from float subtraction (e.g. 5 - 0.5 - 4.3 - 0.2), so
        # compare on a rounded value to keep "exactly booked" in "neutral".
        free_days = round(free_days, FREE_DAYS_PRECISION)
        if free_days > 1.0:
            return "available"
        if free_days > 0.0:
            return "balanced"
        if free_days == 0.0:
            return "neutral"
        if free_days >= -1.0:
            return "tight"
        return "over"

    @staticmethod
    def project_heat_bucket(allocated: float) -> str:
        """Classify project allocation into a bucket."""
        if allocated <= 0:
            return "low"
        if allocated <= PROJECT_ALLOC_MID:
            return "mid"
        if allocated <= PROJECT_ALLOC_HIGH:
            return "high"
        return "over"

